<script setup lang="ts">import {ref} from "vue";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import StatCard from "@/components/zs/StatCard.vue";import AreaChart from "@/components/zs/AreaChart.vue";import DataTable,{type Column} from "@/components/zs/DataTable.vue";import {formatMoney,toMinor} from "@/lib/money";import {setPageMeta} from "@/lib/page-meta";setPageMeta("Cash Flow Forecast","Projected inflows, outflows and closing cash for the active company.");const range=ref("90 days"),series=[{month:"Sep",inflow:14.8,outflow:11.2,balance:31.4},{month:"Oct",inflow:12.1,outflow:14.2,balance:29.3},{month:"Nov",inflow:16.4,outflow:12.8,balance:32.9},{month:"Dec",inflow:18.2,outflow:15.1,balance:36.0}],events=[{id:"1",date:"18 Oct",event:"Supplier payments",type:"Outflow",amount:toMinor(6400000),confidence:"Confirmed"},{id:"2",date:"22 Oct",event:"Receivables collection",type:"Inflow",amount:toMinor(4300000),confidence:"Likely"},{id:"3",date:"30 Oct",event:"Monthly payroll",type:"Outflow",amount:toMinor(9320000),confidence:"Confirmed"}];const columns:Column[]=[{key:"date",header:"Date"},{key:"event",header:"Cash event"},{key:"type",header:"Direction"},{key:"amount",header:"Amount",align:"right",class:"num"},{key:"confidence",header:"Confidence"}];</script><template><AppShell><PageHeader title="Cash Flow Forecast" description="Forward view based on posted books and scheduled company commitments"><template #actions><select v-model="range" class="field w-36"><option>30 days</option><option>60 days</option><option>90 days</option><option>Custom</option></select></template></PageHeader><div class="mb-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Current cash" :value="formatMoney(toMinor(31440800))" tone="brand"/><StatCard label="Projected inflows" :value="formatMoney(toMinor(46700000))" tone="success"/><StatCard label="Projected outflows" :value="formatMoney(toMinor(43300000))" tone="warning"/><StatCard label="90-day closing" :value="formatMoney(toMinor(34840800))"/></div><div class="grid gap-4 xl:grid-cols-[1fr_25rem]"><Panel title="Cash position" description="Solid line is projected closing cash"><div class="p-4"><AreaChart :data="series" x-key="month" :series="[{key:'balance',color:'var(--chart-1)',id:'cash-balance'},{key:'inflow',color:'var(--chart-2)',id:'cash-in'}]" :height="280"/></div></Panel><Panel title="Upcoming pressure points"><DataTable :columns="columns" :rows="events" :min-width="520"><template #date="{row}">{{row.date}}</template><template #event="{row}">{{row.event}}</template><template #type="{row}"><span :class="row.type==='Inflow'?'text-success':'text-warning-strong'">{{row.type}}</span></template><template #amount="{row}">{{formatMoney(row.amount)}}</template><template #confidence="{row}">{{row.confidence}}</template></DataTable></Panel></div></AppShell></template>